  "b08:tr": {
    "%35": [["azghadi2025", "The average results across 25 hectares of field trials show that spot spraying on sugarcane farms is 97\\% as effective as broadcast spraying and reduces herbicide usage by 35\\%, proportionally to the weed density."]],
    "%47": [["allmendinger2024", "Early spot spraying saved 47% of herbicides compared to the broadcast herbicide application."]],
    "%97": [["azghadi2025", "The average results across 25 hectares of field trials show that spot spraying on sugarcane farms is 97\\% as effective as broadcast spraying and reduces herbicide usage by 35\\%, proportionally to the weed density."]],
    "%65": [["azghadi2025", "For specific trial strips with lower weed pressure, spot spraying reduced herbicide usage by up to 65\\%."]],
    "%39": [["azghadi2025", "Water quality measurements of irrigation-induced runoff, three to six days after spraying, showed reductions in the mean concentration and mean load of herbicides of 39\\% and 54\\%, respectively, compared to broadcast spraying."]],
    "%54": [["azghadi2025", "Water quality measurements of irrigation-induced runoff, three to six days after spraying, showed reductions in the mean concentration and mean load of herbicides of 39\\% and 54\\%, respectively, compared to broadcast spraying."], ["mohanty2016", "within the PlantVillage data set of 54,306 images containing 38 classes of 14 crop species and 26 diseases (or absence thereof), this goal has been achieved as demonstrated by the top accuracy of 99.35%."]],
    "%94": [["allmendinger2024", "On average, 94% of all weed plants were correctly identified in the UAV images with the automatic classifier."]],
    "%86": [["allmendinger2024", "Spot-spraying achieved up to 86% WCE, which was equal to the broadcast herbicide treatment."]],
    "%59": [["deere2024", "The AI-powered weed-sensing technology demonstrated an average herbicide savings of 59%** on corn, soybean and cotton fields across the U.S."]],
    "%50": [["deere2025", "In 2025, John Deere customers reduced non-residual herbicide use by an average of nearly 50%—saving nearly 31 million gallons of herbicide mix"]],
    "54.306": [["mohanty2016", "within the PlantVillage data set of 54,306 images containing 38 classes of 14 crop species and 26 diseases (or absence thereof), this goal has been achieved as demonstrated by the top accuracy of 99.35%."]],
    "%99,35": [["mohanty2016", "within the PlantVillage data set of 54,306 images containing 38 classes of 14 crop species and 26 diseases (or absence thereof), this goal has been achieved as demonstrated by the top accuracy of 99.35%."]],
