    "20": [["nasa_2019_landsat", "After the 2008 USGS decision to make Landsat data available at no cost, data use has increased 20-fold, and Landsat-based scientific publications has increased four-fold."], ["sentiwiki_sentinel2", "Each of the satellites in the Sentinel-2 mission carries a single payload: the optical Multi-Spectral Instrument (MSI) that samples 13 spectral bands: four bands at 10 m, six bands at 20 m and three bands at 60 m spatial resolution."]],
    "3,45": [["usgs_2019_landsat", "Landsat imagery provided domestic and international users an estimated \$3.45 billion in benefits in 2017 compared to \$2.19 billion in 2011, with U.S. users accounting for \$2.06 billion of those benefits."]],
    "2,19": [["usgs_2019_landsat", "Landsat imagery provided domestic and international users an estimated \$3.45 billion in benefits in 2017 compared to \$2.19 billion in 2011, with U.S. users accounting for \$2.06 billion of those benefits."]],
