    "13": [["sentiwiki_sentinel2", "Each of the satellites in the Sentinel-2 mission carries a single payload: the optical Multi-Spectral Instrument (MSI) that samples 13 spectral bands: four bands at 10 m, six bands at 20 m and three bands at 60 m spatial resolution."], ["whitcraft_2015", "we employ 10–13years of twice daily 0.05° MODIS Terra (AM) and Aqua (PM) surface reflectance quality assessment cloud flags"]],
    "10": [["sentiwiki_sentinel2", "Each of the satellites in the Sentinel-2 mission carries a single payload: the optical Multi-Spectral Instrument (MSI) that samples 13 spectral bands: four bands at 10 m, six bands at 20 m and three bands at 60 m spatial resolution."], ["whitcraft_2015", "we employ 10–13years of twice daily 0.05° MODIS Terra (AM) and Aqua (PM) surface reflectance quality assessment cloud flags"]],
