    "%30": [["israil_snc_2025", "Investment remained strong, with 33 funding rounds exceeding \$1 million, and more than 30% of all investments directed toward robotics and farm equipment startups."], ["afrika_cta_2019", "the number of highly active users is likely even lower – i.e., likely in the 15–30% range, on average (based on self-reported data) across all use case areas."]],
    "390": [["afrika_cta_2019", "As of 2019, there are at least 390 distinct, active D4Ag solutions across the continent."]],
    "33": [["israil_snc_2025", "Investment remained strong, with 33 funding rounds exceeding \$1 million, and more than 30% of all investments directed toward robotics and farm equipment startups."], ["afrika_cta_2019", "D4Ag solutions have already registered over 33 million smallholder farmers and pastoralists across the continent (13% of all Sub-Saharan African smallholders and pastoralists and up to 45% of smallholder households, depending on assumptions used to calculate penetration)."]],
    "%42": [["afrika_cta_2019", "Our estimates suggest that 42% of registered farmers and pastoralists actually used the solutions they registered for with any frequency."]],
    "%15-30": [["afrika_cta_2019", "the number of highly active users is likely even lower – i.e., likely in the 15–30% range, on average (based on self-reported data) across all use case areas."]],
    "%20": [["afrika_cta_2019", "Based on interviews and smallholder survey data from countries like Kenya, we estimated 20% duplication (i.e., users registered to multiple D4Ag solutions), which would mean ~26 million unique users today."], ["afrika_au_2024", "In Africa, the rapid adoption of smartphones and increased use of the Internet, which has jumped from 20% in 2015 to 40% in 2023"]],
    "26": [["hindistan_pib_2026_agristack", "Further, during Rabi 2025-26, the Digital Crop Survey (DCS) was conducted in 648 Districts covering more than 31.3 crore plots across the country."], ["afrika_cta_2019", "Based on interviews and smallholder survey data from countries like Kenya, we estimated 20% duplication (i.e., users registered to multiple D4Ag solutions), which would mean ~26 million unique users today."]],
    "175": [["afrika_cta_2019", "We estimate approximately €175 million in annual donor funding flows for D4Ag."]],
    "47": [["afrika_cta_2019", "Private sector investment is even more limited – in 2018, there was investment of approximately €47 million into African or Africa-focused D4Ag enterprises, including both start-ups and later stage enterprises."]],
