    "120": [["baul_2024", "The remaining 120 villages were assigned to the control (standard NRLM in-person training with no DG video add-on)."], ["rti_2017_greenseeker", "These technicians received a bonus of 120 pesos per hectare of sensor technology transferred."]],
    "5-12%": [["baul_2024", "Overall, the Bayesian estimation paints a clear picture that DG provides additive benefits to traditional NLRM training alone resulting in a 5%–12% increase in output, 12%–18% increase in yield and 9%–24% increase in estimated profits."]],
    "12-18%": [["baul_2024", "Overall, the Bayesian estimation paints a clear picture that DG provides additive benefits to traditional NLRM training alone resulting in a 5%–12% increase in output, 12%–18% increase in yield and 9%–24% increase in estimated profits."]],
    "9-24%": [["baul_2024", "Overall, the Bayesian estimation paints a clear picture that DG provides additive benefits to traditional NLRM training alone resulting in a 5%–12% increase in output, 12%–18% increase in yield and 9%–24% increase in estimated profits."]],
    "96": [["baul_2024", "The marginal cost of the DG arm is 96 Rps per farmer."]],
    "20": [["moyo_2020", "In 2014, at each scheme, 20 irrigators (of the 75 and 100 in Mkoba and Silalatshani, respectively) were given two WFDs and a Chameleon sensor array."], ["eastwood_2026", "A qualitative research approach was used, with 60- to 90-min semistructured interviews conducted with 20 New Zealand dairy farmers (participants)."]],
    "100%": [["moyo_2020", "Water productivity increased by more than 100% for farmers both with and without monitoring tools."]],
    "48,000": [["rti_2017_greenseeker", "Since the initial pilot phase in 2006, farmers have applied the technology to more than 48,000 cumulative hectares of land throughout the Yaqui Valley (see regional distribution of application over last 3 years in Figure 1)."]],
    "37": [["mrisho_2020", "For all disease/pest damage conditions, mild symptoms were correctly identified by PlantVillage Nuru with much lower accuracy (13–37%) than intermediate symptoms (27–83%), whilst symptoms that were considered to be unclear were identified with moderate accuracy (23–63%) (Table 3)."], ["rti_2017_greenseeker", "Initial data analysis conducted by RTI and CIMMYT reveals that the tool has led to \$37 in additional farmer profits per hectare, totaling \$1.8M of additional profits over an 8-year time period (see Table 1)."]],
    "2,000": [["lapidus_2022", "The technology has been utilized on nearly 2,000 farmer fields representing more than 60,000 hectares in three regions of Mexico."]],
    "60,000": [["lapidus_2022", "The technology has been utilized on nearly 2,000 farmer fields representing more than 60,000 hectares in three regions of Mexico."]],
    "2.6": [["mrisho_2020", "Additionally, the CaSRAT assessment was conducted twice in order to evaluate potential improvements over time, firstly using PlantVillage Nuru V1.05 (released in March 2018) and secondly with PlantVillage Nuru V2.6.0-39 (released in June 2020)."], ["lapidus_2022", "Specifically, farmer field-level data and locally derived greenhouse gas emission factors were analyzed and use of the GreenSeeker Handheld was estimated to have led to a total of \$2.6 M USD in additional profits and more than 14,300 tons CO2e of avoided emissions."]],
    "14,300": [["lapidus_2022", "Specifically, farmer field-level data and locally derived greenhouse gas emission factors were analyzed and use of the GreenSeeker Handheld was estimated to have led to a total of \$2.6 M USD in additional profits and more than 14,300 tons CO2e of avoided emissions."]],
    "35": [["rti_2017_greenseeker", "The umbrella organization for the farmer credit unions, AOASS, had a change in leadership prior to the 2015–2016 growing season, coinciding with the worst climatic conditions in more than 35 years, resulting in extremely low yields."]],
    "14%": [["lepage_2014", "Finally, despite a chaotic beginning of the experiment—the experimental plot had not been irrigated to get rid of a slaking crust, which prevented good emergence—our plot caught up and yielded almost the same grain crop with 14% less irrigation water."]],
    "1-3": [["mrisho_2020", "Additionally, the CaSRAT assessment was conducted twice in order to evaluate potential improvements over time, firstly using PlantVillage Nuru V1.05 (released in March 2018) and secondly with PlantVillage Nuru V2.6.0-39 (released in June 2020)."], ["rti_2017_greenseeker", "Since the initial pilot phase in 2006, farmers have applied the technology to more than 48,000 cumulative hectares of land throughout the Yaqui Valley (see regional distribution of application over last 3 years in Figure 1)."], ["eastwood_2026", "Farmers interviewed were using a VF technology (Halter, Auckland, NZ) that was in an early innovation stage (Marmont et al., 2024) and had been using the technology for 1 to 3 years."]],
